package com.lendup.reservas.config.security;
import static org.junit.jupiter.api.Assertions.*; import jakarta.servlet.FilterChain; import org.junit.jupiter.api.Test; import org.springframework.mock.web.*; import org.springframework.security.core.context.SecurityContextHolder;
class FirebaseAuthenticationFilterTest { @Test void tokenAusenteNoAutenticaYLaCadenaDecide401()throws Exception{SecurityContextHolder.clearContext();var req=new MockHttpServletRequest();var res=new MockHttpServletResponse();new FirebaseAuthenticationFilter(t->new VerifiedToken("ignored",true,false)).doFilter(req,res,(a,b)->{});assertNull(SecurityContextHolder.getContext().getAuthentication());}
  @Test void correoNoVerificadoDevuelve403()throws Exception{var req=new MockHttpServletRequest();req.addHeader("Authorization","Bearer valid");var res=new MockHttpServletResponse();new FirebaseAuthenticationFilter(t->new VerifiedToken("11111111-1111-1111-1111-111111111111",false,false)).doFilter(req,res,(a,b)->fail());assertEquals(403,res.getStatus());assertTrue(res.getContentAsString().contains("EMAIL_NOT_VERIFIED"));}
  @Test void tokenInvalidoDevuelve401()throws Exception{var req=new MockHttpServletRequest();req.addHeader("Authorization","Bearer invalid");var res=new MockHttpServletResponse();new FirebaseAuthenticationFilter(t->{throw new SecurityException();}).doFilter(req,res,(a,b)->fail());assertEquals(401,res.getStatus());}
  @Test void tokenVerificadoAutenticaUidSinConfiarEnHeadersDeRol()throws Exception{SecurityContextHolder.clearContext();var req=new MockHttpServletRequest();req.addHeader("Authorization","Bearer valid");req.addHeader("X-Role","ADMINISTRADOR");var res=new MockHttpServletResponse();new FirebaseAuthenticationFilter(t->new VerifiedToken("11111111-1111-1111-1111-111111111111",true,false)).doFilter(req,res,(a,b)->{});assertTrue(SecurityContextHolder.getContext().getAuthentication().getAuthorities().isEmpty());}
}
